def families():
    out=[]
    for category, text in SOURCE.items():
        for i,line in enumerate(text.strip().splitlines()):
            values=line.split('|')
            assert len(values)==8,(category,i,len(values))
            topic_en,topic_es,context_en,context_es,request_en,request_es,action_en,action_es=values
            out.append({'family_id':f'{category}-{i+1:02d}','category':category,
                        'en':dict(topic=topic_en,context=context_en,request=request_en,action=action_en),
                        'es':dict(topic=topic_es,context=context_es,request=request_es,action=action_es)})
    return out
